#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret names set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

banner "Publish OpenPocketCine"

say "CI, branch protection, and Actions token/SHA policy are already applied via the API."
say "This walkthrough covers the steps that still need a human: history sign-off,"
say "first-time-contributor workflow approval, flipping visibility, and the security"
say "features GitHub only offers on a public repository."
note "Making the repository public is irreversible for anything already in git history."
pause "Ready to start?"

# ── 1. History ───────────────────────────────────────────────────────────
stage "Confirm git history is safe to publish"
say "gitleaks found no secrets. Hygiene found no captures, LUT dumps, or credential files."
say "Commit authors on main include:"
step "9084979+erik-sutton95@users.noreply.github.com (GitHub noreply)"
step "Eriks.indesign@gmail.com (personal Gmail, 12 commits)"
note "A later deletion does not remove those addresses from history, forks, or clones."
if ! confirm "Publish with those author emails as they are (no history rewrite)?"; then
  warn "Stop here. Rewrite authors with git filter-repo before going public, then re-run."
  exit 1
fi
pause "History is accepted?"

# ── 2. Verify applied settings ───────────────────────────────────────────
stage "Verify branch protection and Actions policy"
say "These should already be on. Spot-check the UI so they did not drift."
open_url "https://github.com/erik-sutton95/OpenPocketCine/settings/branches"
step "main: require a pull request, 1 approval, dismiss stale reviews, conversation resolution."
step "Required check: CI gate, require branches up to date."
step "Do not allow force pushes. Do not allow deletions. Linear history on."
step "Do not check 'Do not allow bypassing the above settings' — solo maintainer needs to merge own PRs."
open_url "https://github.com/erik-sutton95/OpenPocketCine/settings/actions"
step "Actions permissions: Allow all actions. Required SHA-1 version pinning: on."
step "Workflow permissions: Read repository contents and packages permissions. Uncheck 'Allow GitHub Actions to create and approve pull requests'."
pause "Branch protection and Actions match that list?"

# ── 3. Fork PR workflows ─────────────────────────────────────────────────
stage "Require approval for first-time contributors"
say "Once public, fork pull requests run CI on GitHub-hosted runners. Gate first-timers."
open_url "https://github.com/erik-sutton95/OpenPocketCine/settings/actions"
step "Scroll to 'Fork pull request workflows from outside collaborators'."
step "Select 'Require approval for first-time contributors' (not 'Require approval for all outside collaborators' unless you want every fork PR to wait)."
note "CI does not use repository secrets. Labeler uses pull_request_target and does not check out PR code."
pause "First-time contributor approval is set?"

# ── 4. Make public ───────────────────────────────────────────────────────
stage "Change visibility to public"
warn "This cannot be undone for git history. Stars, watchers, and ranking reset if you later go private."
open_url "https://github.com/erik-sutton95/OpenPocketCine/settings"
step "Danger Zone → Change repository visibility → Public."
step "Or let this wizard run: gh repo edit --visibility public --accept-visibility-change-consequences"
if confirm "Flip erik-sutton95/OpenPocketCine to public now via gh?"; then
  if gh repo edit erik-sutton95/OpenPocketCine --visibility public --accept-visibility-change-consequences; then
    say "Repository is public."
  else
    warn "gh could not change visibility. Use the Danger Zone in the browser, then continue."
    pause "Visibility is Public in Settings → General?"
  fi
else
  pause "Flip it in the browser, then press Enter when Settings shows Public."
fi

# ── 5. Security features that need public ────────────────────────────────
stage "Enable secret scanning, push protection, private reporting"
say "GitHub does not offer repository secret scanning on this private repo. It does on public."
open_url "https://github.com/erik-sutton95/OpenPocketCine/settings/security_analysis"
step "Secret Protection / secret scanning → Enable."
step "Push protection → Enable."
step "Private vulnerability reporting → Enable (Security.md already points reporters here)."
step "Dependabot alerts and Dependabot security updates should already be on — leave them on."
note "Optional: CodeQL default setup. Skip unless you want Actions-language alerts; Swift coverage is limited."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  if gh api --method PUT repos/erik-sutton95/OpenPocketCine/private-vulnerability-reporting >/dev/null 2>&1; then
    say "Private vulnerability reporting enabled via API."
  else
    warn "API could not enable private vulnerability reporting — use the Security page toggle."
  fi
  if gh api --method PATCH repos/erik-sutton95/OpenPocketCine --input - >/dev/null 2>&1 <<'JSON'
{
  "security_and_analysis": {
    "secret_scanning": { "status": "enabled" },
    "secret_scanning_push_protection": { "status": "enabled" }
  }
}
JSON
  then
    say "Secret scanning + push protection requested via API."
  else
    warn "API could not enable secret scanning — use the Security page toggles."
  fi
fi
pause "Secret scanning, push protection, and private reporting are on?"

# ── 6. Verify the public surfaces ────────────────────────────────────────
stage "Verify Pages, CI, and Xcode Cloud"
open_url "https://openpocketcine.app/"
step "Landing page still loads over HTTPS. Custom domain openpocketcine.app is unchanged."
open_url "https://github.com/erik-sutton95/OpenPocketCine/actions"
step "Workflow CI is Active (not disabled). After this branch merges, PRs must show a green 'CI gate'."
step "Native Swift/iOS and Android jobs run on public repos (hosted macOS is then free)."
open_url "https://appstoreconnect.apple.com/apps"
step "Xcode Cloud still lists erik-sutton95/OpenPocketCine. Reconnect GitHub if the workflow lost the repo."
note "No GitHub Actions secrets are required for CI. Optional Pages variable: TESTFLIGHT_URL."
pause "Pages, Actions, and Xcode Cloud look healthy?"

finish
